const now = new Date();
const oneWeekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
const sinceIso = oneWeekAgo.toISOString();
const repo = $json.GITHUB_REPO;

return [
  {
    json: {
      ...$json,
      sinceIso,
      commitsUrl: `https://api.github.com/repos/${repo}/commits?since=${sinceIso}&per_page=100`,
      issuesUrl: `https://api.github.com/repos/${repo}/issues?state=closed&since=${sinceIso}&per_page=100`,
      pullsUrl: `https://api.github.com/repos/${repo}/pulls?state=closed&per_page=100`
    }
  }
];

const config = $('Calculate Date Range & URLs').item.json;
const sinceDate = new Date(config.sinceIso);

// 1. Commits
const rawCommits = $('Fetch Weekly Commits').all().map(i => i.json);
const commits = rawCommits.map(c => ({
  sha: c.sha ? c.sha.substring(0, 7) : '',
  author: c.commit && c.commit.author ? c.commit.author.name : 'Unknown',
  message: c.commit ? c.commit.message.split('\n')[0] : ''
})).slice(0, 50);

// 2. Closed issues (exclude PR objects)
const rawIssues = $('Fetch Closed Issues & PRs').all().map(i => i.json);
const closedIssues = rawIssues
  .filter(item => !item.pull_request && item.state === 'closed' && new Date(item.closed_at) >= sinceDate)
  .map(issue => ({
    number: issue.number,
    title: issue.title,
    author: issue.user ? issue.user.login : 'unknown'
  }));

// 3. Merged PRs
const rawPulls = $('Fetch Closed Pull Requests').all().map(i => i.json);
const mergedPRs = rawPulls
  .filter(pr => pr.merged_at && new Date(pr.merged_at) >= sinceDate)
  .map(pr => ({
    number: pr.number,
    title: pr.title,
    author: pr.user ? pr.user.login : 'unknown',
    merged_at: pr.merged_at
  }));

const language = (config.LANGUAGE || 'EN').toUpperCase();
const promptInstruction = language === 'FR' 
  ? 'Rédigez le résumé en français professionnel, dynamique et concis.'
  : 'Write the summary in crisp, professional English.';

const claudePrompt = `You are an elite software release narrator. Analyze the following weekly GitHub telemetry for repository "${config.GITHUB_REPO}" over the last 7 days.

COMMITS (${commits.length}):
${JSON.stringify(commits, null, 2)}

CLOSED ISSUES (${closedIssues.length}):
${JSON.stringify(closedIssues, null, 2)}

MERGED PULL REQUESTS (${mergedPRs.length}):
${JSON.stringify(mergedPRs, null, 2)}

INSTRUCTIONS:
- ${promptInstruction}
- Structure the narrative summary into 4 clean sections:
  1. 🌟 Weekly Executive Highlights (2-3 sentences)
  2. 🚀 Key Features & Architectural Changes
  3. 🐛 Bug Fixes & Stability Improvements
  4. 👥 Active Contributors & Momentum
- Maintain an engaging, high-signal engineering tone suitable for Slack/Discord.
- Keep formatting clean Markdown.`;

return [
  {
    json: {
      ...config,
      stats: {
        commits_count: commits.length,
        issues_closed_count: closedIssues.length,
        prs_merged_count: mergedPRs.length
      },
      claudePrompt
    }
  }
];

const claudeResponse = $input.first().json;
const aggregateData = $('Aggregate Weekly Telemetry & Prompt').item.json;
const narrative = claudeResponse.content && claudeResponse.content[0] 
  ? claudeResponse.content[0].text 
  : 'Weekly summary generated.';

const webhookType = (aggregateData.WEBHOOK_TYPE || 'discord').toLowerCase();
const repo = aggregateData.GITHUB_REPO;

let payload = {};
if (webhookType === 'slack') {
  payload = {
    text: `*Weekly Dev Summary for ${repo}*\n\n${narrative}`
  };
} else {
  // Default Discord embed
  payload = {
    username: 'Claude Dev Narrator',
    avatar_url: 'https://anthropic.com/favicon.ico',
    content: `📊 **Weekly GitHub Dev Summary: ${repo}**\n${narrative.substring(0, 1900)}`
  };
}

return [
  {
    json: {
      destinationUrl: aggregateData.DESTINATION_WEBHOOK_URL,
      payload,
      narrative
    }
  }
];
